import { useState, useEffect, useCallback } from 'react';

const STATUS_MAP = {
  pending_approval: { label: '⏳ Pending Approval', cls: 'status-pending' },
  confirmed:        { label: '✅ Active Rental',     cls: 'status-confirmed' },
  completed:        { label: '🏁 Completed',         cls: 'status-completed' },
  rejected:         { label: '❌ Rejected',          cls: 'status-rejected' },
  cancelled:        { label: '🚫 Cancelled',         cls: 'status-cancelled' },
  failed:           { label: '💳 Payment Failed',    cls: 'status-failed' },
};

function StarPicker({ onSubmit, loading }) {
  const [stars, setStars] = useState(0);
  const [hover, setHover] = useState(0);
  const [comment, setComment] = useState('');

  return (
    <div className="star-form">
      <div className="stars-pick">
        {[1, 2, 3, 4, 5].map((s) => (
          <span
            key={s}
            className={`star-pick-icon ${s <= (hover || stars) ? 'star-filled' : ''}`}
            onClick={() => setStars(s)}
            onMouseEnter={() => setHover(s)}
            onMouseLeave={() => setHover(0)}
          >★</span>
        ))}
      </div>
      <input
        className="rating-comment"
        placeholder="Add a comment (optional)"
        value={comment}
        onChange={(e) => setComment(e.target.value)}
      />
      <button
        className="submit-rating-btn"
        onClick={() => onSubmit(stars, comment)}
        disabled={stars === 0 || loading}
      >
        {loading ? 'Submitting...' : 'Submit Rating'}
      </button>
    </div>
  );
}

function MyRentals({ user }) {
  const [reservations, setReservations] = useState([]);
  const [ratings, setRatings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [cancelLoading, setCancelLoading] = useState(null);
  const [ratingLoading, setRatingLoading] = useState(null);
  const [openRating, setOpenRating] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    const [rRes, ratRes] = await Promise.all([
      fetch('http://localhost:3003/api/reservations'),
      fetch('http://localhost:3003/api/ratings'),
    ]);
    const rData = await rRes.json();
    const ratData = await ratRes.json();
    setReservations(rData.filter((r) => r.userId === user.id));
    setRatings(ratData);
    setLoading(false);
  }, [user.id]);

  useEffect(() => { load(); }, [load]);

  const handleCancel = async (id) => {
    setCancelLoading(id);
    await fetch(`http://localhost:3003/api/reservations/${id}/cancel`, { method: 'PATCH' });
    await load();
    setCancelLoading(null);
  };

  const handleRate = async (reservation, stars, comment) => {
    setRatingLoading(reservation.id);
    await fetch('http://localhost:3003/api/ratings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        reservationId: reservation.id,
        fromUserId: user.id,
        fromName: user.name,
        toUserId: reservation.vehicle.ownerId,
        stars,
        comment,
        type: 'renter_to_owner',
      }),
    });
    setOpenRating(null);
    await load();
    setRatingLoading(null);
  };

  const alreadyRated = (reservationId) =>
    ratings.some((r) => r.reservationId === reservationId && r.fromUserId === user.id && r.type === 'renter_to_owner');

  const ratingFromOwner = (reservationId) =>
    ratings.find((r) => r.reservationId === reservationId && r.type === 'owner_to_renter' && r.toUserId === user.id);

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="my-rentals">
      <h2>My Rentals</h2>

      {reservations.length === 0 ? (
        <p className="no-vehicles">You haven't made any rental requests yet.</p>
      ) : (
        <div className="rentals-list">
          {reservations.slice().reverse().map((r) => {
            const status = STATUS_MAP[r.status] || { label: r.status, cls: '' };
            const rated = alreadyRated(r.id);
            return (
              <div key={r.id} className={`rental-card rental-card-${r.status}`}>
                <div className="rental-card-header">
                  <div className="rental-card-vehicle">
                    <div className="rental-vehicle-img">
                      {r.vehicle?.image ? (
                        <img
                          src={r.vehicle.image.startsWith('http') ? r.vehicle.image : `/images/${r.vehicle.image}`}
                          alt=""
                          onError={(e) => { e.target.style.display = 'none'; e.target.nextSibling.style.display = 'flex'; }}
                        />
                      ) : null}
                      <div className="vehicle-img-fallback small-fallback" style={{ display: r.vehicle?.image ? 'none' : 'flex' }}>🚗</div>
                    </div>
                    <div>
                      <div className="rental-vehicle-name">
                        {r.vehicle?.brand} {r.vehicle?.model}
                      </div>
                      <div className="rental-vehicle-sub">
                        📍 {r.vehicle?.campus} &bull; {r.vehicle?.segment}
                      </div>
                    </div>
                  </div>
                  <span className={`rental-status-badge ${status.cls}`}>{status.label}</span>
                </div>

                <div className="rental-card-body">
                  <div className="rental-detail-row">
                    <span>📅 Dates</span>
                    <strong>{r.startDate} → {r.endDate}</strong>
                  </div>
                  <div className="rental-detail-row">
                    <span>💰 Amount</span>
                    <strong>₺{r.amount}</strong>
                  </div>
                  {r.transactionId && (
                    <div className="rental-detail-row">
                      <span>🔑 Transaction ID</span>
                      <strong className="txid">{r.transactionId}</strong>
                    </div>
                  )}
                  <div className="rental-detail-row">
                    <span>📋 Reservation No</span>
                    <strong>#{r.id}</strong>
                  </div>
                </div>

                <div className="rental-card-footer">
                  {r.status === 'pending_approval' && (
                    <button
                      className="cancel-rental-btn"
                      onClick={() => handleCancel(r.id)}
                      disabled={cancelLoading === r.id}
                    >
                      {cancelLoading === r.id ? 'Cancelling...' : '🚫 Cancel Request'}
                    </button>
                  )}

                  {(r.status === 'confirmed' || r.status === 'completed') && !rated && (
                    <>
                      {openRating === r.id ? (
                        <StarPicker
                          onSubmit={(stars, comment) => handleRate(r, stars, comment)}
                          loading={ratingLoading === r.id}
                        />
                      ) : (
                        <button className="rate-btn" onClick={() => setOpenRating(r.id)}>
                          ⭐ Rate Car Owner
                        </button>
                      )}
                    </>
                  )}

                  {(r.status === 'confirmed' || r.status === 'completed') && rated && (
                    <span className="already-rated">⭐ Rated</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default MyRentals;
